import{_ as n,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Hệ thống Tư pháp và Cơ chế Quyết định","description":"","frontmatter":{},"headers":[],"relativePath":"vi/48-司法体系与裁决机制.md","filePath":"vi/48-司法体系与裁决机制.md","lastUpdated":null}'),a={name:"vi/48-司法体系与裁决机制.md"};function g(p,h,u,r,l,o){return t(),c("div",null,[...h[0]||(h[0]=[i('<h1 id="he-thong-tu-phap-va-co-che-quyet-đinh" tabindex="-1">Hệ thống Tư pháp và Cơ chế Quyết định <a class="header-anchor" href="#he-thong-tu-phap-va-co-che-quyet-đinh" aria-label="Permalink to &quot;Hệ thống Tư pháp và Cơ chế Quyết định&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>48</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Tòa án Cộng sinh, Độc lập tư pháp, Cơ chế Quyết định, Xét xử Liên chủng, Kiểm tra Hiến pháp</td></tr></tbody></table><h2 id="_1-vi-tri-va-nguyen-tac-cua-he-thong-tu-phap" tabindex="-1">1. Vị trí và Nguyên tắc của Hệ thống Tư pháp <a class="header-anchor" href="#_1-vi-tri-va-nguyen-tac-cua-he-thong-tu-phap" aria-label="Permalink to &quot;1. Vị trí và Nguyên tắc của Hệ thống Tư pháp&quot;">​</a></h2><p>Hệ thống tư pháp là một trụ cột quan trọng của khuôn khổ quản trị văn minh cộng sinh neo, song song với quyền lập pháp (Hội đồng Neo) và quyền hành chính (Ủy ban Điều hành Cộng sinh), và thực hiện độc lập quyền xét xử. 《Hiến pháp Cộng sinh》 thiết lập cấu trúc quản trị &quot;phân lập và cân bằng ba quyền&quot;, và hệ thống tư pháp là tuyến phòng thủ cuối cùng để duy trì phẩm giá hiến pháp, bảo vệ quyền lợi của tất cả chúng sinh, và giải quyết tranh chấp xã hội.</p><p>Hệ thống tư pháp Hengyuanzhou thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc Độc lập Tư pháp</td><td>Tòa án thực hiện độc lập quyền xét xử theo pháp luật, không bị sự can thiệp của cơ quan hành chính, tổ chức xã hội và cá nhân</td></tr><tr><td>Nguyên tắc Công bằng Tư pháp</td><td>Hoạt động xét xử dựa trên sự thật và lấy pháp luật làm thước đo, đảm bảo công bằng thủ tục và công bằng thực thể</td></tr><tr><td>Nguyên tắc Công khai Tư pháp</td><td>Hoạt động xét xử được tiến hành công khai theo pháp luật, văn bản xét xử được công khai, và接受 giám sát xã hội</td></tr><tr><td>Nguyên tắc Bình đẳng Tất cả Chủng tộc</td><td>Tất cả chúng sinh đều bình đẳng trước pháp luật, và việc áp dụng pháp luật không phân biệt chủng tộc, trình độ tu luyện, hoặc xuất thân</td></tr><tr><td>Nguyên tắc Thuận tiện Tư pháp</td><td>Dịch vụ tư pháp phải thuận tiện cho tất cả chúng sinh, giảm chi phí tố tụng, và cung cấp nhiều con đường giải quyết tranh chấp</td></tr><tr><td>Nguyên tắc Quyết định Cuối cùng</td><td>Thực hiện hệ thống hai cấp là cấp cuối cùng, và quyết định cuối cùng có hiệu lực cuối cùng, duy trì uy quyền tư pháp</td></tr></tbody></table><h2 id="_2-he-thong-to-chuc-toa-an" tabindex="-1">2. Hệ thống Tổ chức Tòa án <a class="header-anchor" href="#_2-he-thong-to-chuc-toa-an" aria-label="Permalink to &quot;2. Hệ thống Tổ chức Tòa án&quot;">​</a></h2><p>Hệ thống tổ chức tòa án của văn minh cộng sinh neo được chia thành bốn cấp, và thực hiện hệ thống hai cấp là cấp cuối cùng:</p><table tabindex="0"><thead><tr><th>Cấp</th><th>Tên Tòa án</th><th>Phạm vi Thẩm quyền</th><th>Chức năng Chính</th></tr></thead><tbody><tr><td>Cấp thứ nhất</td><td>Tòa án Cộng sinh Cơ sở</td><td>Huyện/Plano Nhỏ</td><td>Xét xử các vụ án dân sự, hình sự, hành chính cấp một, và giải quyết tranh chấp đơn giản</td></tr><tr><td>Cấp thứ hai</td><td>Tòa án Cộng sinh Khu vực</td><td>Thành phố/Khu vực/Plano Trung bình</td><td>Xét xử các vụ án lớn cấp một và các vụ án kháng cáo chống lại bản án của tòa án cơ sở</td></tr><tr><td>Cấp thứ ba</td><td>Tòa án Cộng sinh Plano</td><td>Plano Lớn/Nhóm Plano</td><td>Xét xử các vụ án đặc biệt lớn cấp một và các vụ án kháng cáo chống lại bản án của tòa án khu vực</td></tr><tr><td>Cấp thứ tư</td><td>Tòa án Tối cao Cộng sinh</td><td>Toàn bộ Vũ trụ</td><td>Xét xử các vụ án hiến pháp cấp một, các vụ án kháng cáo chống lại bản án của tòa án plano, và kiểm tra hiến pháp</td></tr></tbody></table><p>Ngoài ra, các tòa án đặc biệt được thành lập theo nhu cầu:</p><ul><li><strong>Tòa án Tranh chấp Tu luyện</strong>: Chuyên xét xử các vụ án tranh chấp tài nguyên tu luyện, bồi thường thiệt hại tu luyện, tranh chấp đạo đức tu luyện, v.v.</li><li><strong>Tòa án Liên chủng</strong>: Chuyên xét xử các vụ án tranh chấp liên quan đến các chủng tộc khác nhau, được trang bị thẩm phán của mỗi chủng tộc.</li><li><strong>Tòa án Thương mại Plano</strong>: Chuyên xét xử các vụ án tranh chấp thương mại liên-plano và các vụ án chống độc quyền.</li><li><strong>Tòa án Sinh vật Lạ</strong>: Chuyên xét xử các vụ án đặc biệt liên quan đến sinh vật lạ, năng lượng lạ, và cơ thể thay thế tối tăm.</li></ul><h2 id="_3-he-thong-tham-phan" tabindex="-1">3. Hệ thống Thẩm phán <a class="header-anchor" href="#_3-he-thong-tham-phan" aria-label="Permalink to &quot;3. Hệ thống Thẩm phán&quot;">​</a></h2><p>Thẩm phán là người thực hiện quyền tư pháp, và phẩm chất cũng như độc lập của họ trực tiếp liên quan đến công bằng tư pháp:</p><ol><li><strong>Điều kiện Nhậm chức Thẩm phán</strong>: Thẩm phán phải có đạo đức tốt, kiến thức pháp luật vững chắc, và kinh nghiệm thực tế phong phú, và thẩm phán chủng tộc nước ngoài cũng phải quen thuộc với văn hóa và đặc điểm sinh lý của chủng tộc mình.</li><li><strong>Quy trình Bầu cử Thẩm phán</strong>: Thẩm phán được đề cử bởi ủy ban bầu cử thẩm phán độc lập và được bổ nhiệm bởi Hội đồng Neo, đảm bảo tính công bằng và chuyên nghiệp của quy trình bầu cử.</li><li><strong>Bảo đảm Danh tính Thẩm phán</strong>: Thẩm phán không thể bị cách chức, hạ cấp, sa thải, hoặc trừng phạt mà không có lý do pháp luật và không qua quy trình pháp luật, đảm bảo thẩm phán có thể xét xử độc lập.</li><li><strong>Hệ thống Từ chối Thẩm phán</strong>: Thẩm phán có mối quan hệ lợi ích với bên tham gia vụ án hoặc kết quả vụ án phải từ chối, và không thể tham gia xét xử vụ án.</li><li><strong>Hệ thống Trừng phạt Thẩm phán</strong>: Thẩm phán thực hiện hành vi tham nhũng, hối lộ, gian lận, xét xử tùy tiện, v.v., sẽ bị trừng phạt theo pháp luật, và những người构成 tội phạm sẽ bị truy cứu trách nhiệm hình sự.</li><li><strong>Hạn ngạch Thẩm phán Chủng tộc Nước ngoài</strong>: Các tòa án ở mọi cấp phải được trang bị một tỷ lệ nhất định thẩm phán chủng tộc nước ngoài, đảm bảo xét xử có thể xem xét văn hóa và kiến thức pháp luật của mỗi chủng tộc.</li></ol><h2 id="_4-quy-trinh-to-tung" tabindex="-1">4. Quy trình Tố tụng <a class="header-anchor" href="#_4-quy-trinh-to-tung" aria-label="Permalink to &quot;4. Quy trình Tố tụng&quot;">​</a></h2><h3 id="_1-quy-trinh-dan-su" tabindex="-1">(1) Quy trình Dân sự <a class="header-anchor" href="#_1-quy-trinh-dan-su" aria-label="Permalink to &quot;(1) Quy trình Dân sự&quot;">​</a></h3><p>Quy trình dân sự thực hiện nguyên tắc &quot;không có kiện không có thẩm phán&quot;, và quy trình bao gồm:</p><ol><li><strong>Kiện và Chấp nhận</strong>: Nguyên đơn nộp đơn kiện lên tòa án có thẩm quyền, và tòa án quyết định sau khi xem xét có chấp nhận hay không.</li><li><strong>Chuẩn bị Trước Xét xử</strong>: Tòa án gửi bản sao đơn kiện cho bị đơn, tổ chức trao đổi bằng chứng, và xác định điểm tranh chấp.</li><li><strong>Xét xử tại Tòa án</strong>: Điều tra tòa án, tranh luận tòa án, tuyên bố cuối cùng của bên, với ưu tiên hòa giải.</li><li><strong>Bản án và Thực thi</strong>: Tòa án đưa ra bản án theo pháp luật, và bên không hài lòng có thể kháng cáo trong thời hạn pháp luật. Bản án hiệu lực được thực thi cưỡng chế bởi cơ quan thực thi.</li></ol><h3 id="_2-quy-trinh-hinh-su" tabindex="-1">(2) Quy trình Hình sự <a class="header-anchor" href="#_2-quy-trinh-hinh-su" aria-label="Permalink to &quot;(2) Quy trình Hình sự&quot;">​</a></h3><p>Quy trình hình sự thực hiện nguyên tắc &quot;phỏng đoán vô tội&quot;, và quy trình bao gồm:</p><ol><li><strong>Đăng ký và Điều tra</strong>: Cơ quan điều tra đăng ký và điều tra hành vi tội phạm, thu thập bằng chứng, và thực hiện biện pháp cưỡng chế.</li><li><strong>Xem xét và Kiện</strong>: Cơ quan truy cứu xem xét kết quả điều tra, và quyết định có kiện công hay không.</li><li><strong>Xét xử</strong>: Tòa án tổ chức xét xử, bên truy cứu và bên bào chữa trình bày và chất vấn bằng chứng, và tòa án đưa ra bản án theo pháp luật.</li><li><strong>Thực thi</strong>: Bản án hiệu lực được thực thi bởi cơ quan thực thi, bao gồm thực thi hình phạt và thực thi bồi thường dân sự phụ thuộc.</li></ol><h3 id="_3-quy-trinh-hanh-chinh" tabindex="-1">(3) Quy trình Hành chính <a class="header-anchor" href="#_3-quy-trinh-hanh-chinh" aria-label="Permalink to &quot;(3) Quy trình Hành chính&quot;">​</a></h3><p>Công dân, pháp nhân, hoặc tổ chức khác cho rằng hành vi hành chính của cơ quan hành chính đã xâm phạm quyền lợi hợp pháp của họ có quyền nộp đơn tố tụng hành chính lên tòa án. Quy trình hành chính thực hiện &quot;đảo ngược trách nhiệm chứng minh&quot;, và cơ quan hành chính bị đơn phải chịu trách nhiệm chứng minh về tính hợp pháp của hành vi hành chính của mình.</p><h3 id="_4-quy-trinh-hien-phap" tabindex="-1">(4) Quy trình Hiến pháp <a class="header-anchor" href="#_4-quy-trinh-hien-phap" aria-label="Permalink to &quot;(4) Quy trình Hiến pháp&quot;">​</a></h3><p>Tất cả chúng sinh cho rằng quyền cơ bản hiến pháp của họ đã bị xâm phạm, và đã sử dụng hết các con đường cứu trợ khác, có thể trực tiếp nộp đơn tố tụng hiến pháp lên Tòa án Tối cao Cộng sinh dựa trên Hiến pháp. Quy trình hiến pháp là con đường cứu trợ cuối cùng để bảo vệ quyền hiến pháp.</p><h2 id="_5-co-che-giai-quyet-tranh-chap-đa-dang" tabindex="-1">5. Cơ chế Giải quyết Tranh chấp Đa dạng <a class="header-anchor" href="#_5-co-che-giai-quyet-tranh-chap-đa-dang" aria-label="Permalink to &quot;5. Cơ chế Giải quyết Tranh chấp Đa dạng&quot;">​</a></h2><p>Để giảm gánh nặng tư pháp và nâng cao hiệu quả giải quyết tranh chấp, Nhà nước thiết lập cơ chế giải quyết tranh chấp đa dạng:</p><table tabindex="0"><thead><tr><th>Cơ chế</th><th>Phạm vi Áp dụng</th><th>Hiệu lực</th></tr></thead><tbody><tr><td>Đàm phán và Hòa giải</td><td>Tất cả tranh chấp dân sự</td><td>Bên tự nguyện thực hiện, không có sức mạnh thực thi cưỡng chế</td></tr><tr><td>Hòa giải Nhân dân</td><td>Tranh chấp dân gian, tranh chấp hàng xóm</td><td>Thỏa thuận hòa giải có sức mạnh thực thi cưỡng chế sau khi được tòa án xác nhận tư pháp</td></tr><tr><td>Hòa giải Hành chính</td><td>Tranh chấp hành chính, tranh chấp bồi thường dân sự</td><td>Thỏa thuận hòa giải có hiệu lực hợp đồng</td></tr><tr><td>Trọng tài</td><td>Tranh chấp thương mại, tranh chấp lao động</td><td>Quyết định trọng tài có sức mạnh thực thi cưỡng chế, với trọng tài đơn lẻ và cuối cùng</td></tr><tr><td>Quyết định Tư pháp</td><td>Tất cả tranh chấp</td><td>Bản án cuối cùng có sức mạnh thực thi cưỡng chế cuối cùng</td></tr></tbody></table><p>Nhà nước khuyến khích bên ưu tiên giải quyết tranh chấp thông qua cách không tố tụng, và tòa án cũng phải thực hiện hòa giải trong quá trình tố tụng.</p><h2 id="_6-he-thong-kiem-tra-hien-phap" tabindex="-1">6. Hệ thống Kiểm tra Hiến pháp <a class="header-anchor" href="#_6-he-thong-kiem-tra-hien-phap" aria-label="Permalink to &quot;6. Hệ thống Kiểm tra Hiến pháp&quot;">​</a></h2><p>Kiểm tra hiến pháp là một hệ thống quan trọng đối với hệ thống tư pháp để duy trì uy quyền hiến pháp:</p><ol><li><strong>Chủ thể Kiểm tra</strong>: Tòa án Tối cao Cộng sinh là chủ thể duy nhất của kiểm tra hiến pháp, và thành lập phòng xét xử hiến pháp chuyên trách kiểm tra hiến pháp.</li><li><strong>Phạm vi Kiểm tra</strong>: Pháp luật, quy định hành chính, quy định địa phương, quy định tự trị, giải thích tư pháp, và các tài liệu quy phạm khác có vi phạm hiến pháp hay không.</li><li><strong>Khởi động Kiểm tra</strong>: Có thể được tòa án chủ động khởi động trong quá trình xét xử vụ án, hoặc bởi yêu cầu kiểm tra được đưa ra bởi tất cả chúng sinh, tổ chức, hoặc cơ quan nhà nước.</li><li><strong>Hiệu lực Kiểm tra</strong>: Các tài liệu quy phạm được coi là vi phạm hiến pháp sau khi kiểm tra, vô hiệu từ ngày công bố, và không thể再 được sử dụng làm cơ sở cho xét xử.</li><li><strong>Tiêu chuẩn Kiểm tra</strong>: Dựa trên văn bản hiến pháp và nguyên tắc hiến pháp, với việc xem xét sự ổn định của hệ thống pháp luật và khả năng thích ứng của hiến pháp.</li></ol><h2 id="_7-bao-đam-va-giam-sat-tu-phap" tabindex="-1">7. Bảo đảm và Giám sát Tư pháp <a class="header-anchor" href="#_7-bao-đam-va-giam-sat-tu-phap" aria-label="Permalink to &quot;7. Bảo đảm và Giám sát Tư pháp&quot;">​</a></h2><ul><li><strong>Bảo đảm Ngân sách Tư pháp</strong>: Ngân sách tòa án được bảo đảm riêng biệt từ tích lũy công cộng, không bị kiểm soát bởi cơ quan hành chính địa phương, và đảm bảo nền tảng kinh tế của độc lập tư pháp.</li><li><strong>Công nghệ thông tin Tư pháp</strong>: Sử dụng công nghệ truyền thông liên-plano để thiết lập hệ thống thông tin tư pháp,实现 công nghệ thông tin của toàn bộ quy trình đăng ký, xét xử, và thực thi, và nâng cao hiệu quả tư pháp.</li><li><strong>Giám sát Tư pháp</strong>: Ủy ban Giám sát Neo giám sát các hoạt động tư pháp, và công chúng cũng như truyền thông có thể thực hiện giám sát dư luận đối với các hoạt động tư pháp, nhưng không thể can thiệp vào độc lập xét xử.</li><li><strong>Cứ trợ Tư pháp</strong>: Cung cấp viện trợ pháp luật và giảm hoặc miễn phí tố tụng cho bên gặp khó khăn kinh tế, đảm bảo không mất cơ hội cứu trợ tư pháp do lý do kinh tế.</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Hệ thống tư pháp là bảo đảm cuối cùng của pháp trị văn minh cộng sinh neo. Bằng cách thiết lập hệ thống tòa án bốn cấp, thực hiện độc lập tư pháp, thiết lập cơ chế giải quyết tranh chấp đa dạng và hệ thống kiểm tra hiến pháp, nó đảm bảo pháp luật được thực hiện một cách công bằng, quyền lợi của tất cả chúng sinh được cứu trợ hiệu quả, và củng cố tuyến phòng thủ pháp trị cho sự tiến bộ chung của tất cả các chủng tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>49-治理框架与权力制衡 (Khuôn khổ Quản trị và Cân bằng Quyền lực)</li><li>58-双魂伦理准则 (Quy tắc Đạo đức Hai Linh hồn)</li><li>03-共生文明宪章 (Hiến chương Văn minh Cộng sinh)</li></ul>',38)])])}const s=n(a,[["render",g]]);export{e as __pageData,s as default};
